package com.taskora.milesora.config;
import com.taskora.milesora.model.*;import com.taskora.milesora.repo.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import java.util.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@Configuration public class SeedData { @Bean CommandLineRunner seed(UserRepository users, ProjectRepository projects, TaskRepository tasks){return args->{if(users.count()==0){String[][] rows={{"admin@taskora.io","admin","Admin@123","System Administrator","ADMIN","System Administrator"},{"manager@taskora.io","manager","Manager@123","Project Manager","PROJECT_MANAGER","Project Manager"},{"employee@taskora.io","employee","Employee@123","Team Member","EMPLOYEE","Software Engineer"}};for(String[] r:rows){UserEntity u=new UserEntity();u.email=r[0];u.username=r[1];u.password=new BCryptPasswordEncoder().encode(r[2]);u.name=r[3];u.role=r[4];u.title=r[5];users.save(u);}} if(projects.count()==0){ProjectEntity p=new ProjectEntity();p.name="Welcome to Taskora Pulse";p.keyCode="WTP";p.description="Your first project. Edit or delete it from the Projects page.";p.status="ACTIVE";p.priority="MEDIUM";p.managerId=2L;projects.save(p);TaskEntity t=new TaskEntity();t.title="Explore the workspace";t.description="Open the task and update its status.";t.status="TO_DO";t.priority="MEDIUM";t.projectId=p.id;t.assigneeId=3L;tasks.save(t);}};} }
